package com.example.starter.dao;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/**
 * 全局空域版本单行表访问。审核与禁飞区变更均先对该行加排他锁，
 * 保证版本号与禁飞区集合来自一致状态。
 */
@Repository
public class AirspaceDao {

    private final JdbcTemplate jdbc;

    public AirspaceDao(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 读取当前全局空域版本（不加锁，仅用于只读查询）。
     */
    public long currentVersion() {
        Long version = jdbc.queryForObject("SELECT version FROM airspace_state WHERE id = 1", Long.class);
        return version == null ? 0L : version;
    }

    /**
     * 排他锁定版本行并读取版本号；须在事务内调用，用于串行化空域变更与审核。
     */
    public long lockAndGetVersion() {
        Long version = jdbc.queryForObject(
                "SELECT version FROM airspace_state WHERE id = 1 FOR UPDATE", Long.class);
        return version == null ? 0L : version;
    }

    /**
     * 全局空域版本加一；须在持有版本行排他锁的事务内调用。
     */
    public void incrementVersion() {
        jdbc.update("UPDATE airspace_state SET version = version + 1 WHERE id = 1");
    }
}

package com.example.starter.dao;

import com.example.starter.domain.Zone;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.sql.Timestamp;
import java.time.Instant;
import java.util.List;
import java.util.Optional;

/**
 * 禁飞区表访问：仅支持创建与撤销，撤销保留行并置 active=FALSE。
 */
@Repository
public class ZoneDao {

    private static final RowMapper<Zone> MAPPER = (rs, rowNum) -> new Zone(
            rs.getString("zone_id"),
            rs.getInt("min_x"),
            rs.getInt("min_y"),
            rs.getInt("max_x"),
            rs.getInt("max_y"),
            rs.getBoolean("active"));

    private final JdbcTemplate jdbc;

    public ZoneDao(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 按主键查询禁飞区（含已撤销）。
     */
    public Optional<Zone> findById(String zoneId) {
        List<Zone> zones = jdbc.query("SELECT * FROM zones WHERE zone_id = ?", MAPPER, zoneId);
        return zones.stream().findFirst();
    }

    /**
     * 查询全部有效禁飞区。
     */
    public List<Zone> findActive() {
        return jdbc.query("SELECT * FROM zones WHERE active = TRUE", MAPPER);
    }

    /**
